def _extract_constants_from_ast(source_path: str) -> Dict[str, Any]:
    """Extract constant assignments from a Python source file's AST.

    Returns a dict of {name: value} for simple assignments like:
        THRESHOLD = 0.5
        MAX_ROUNDS = 20
        tau_sim = 0.33

    Only extracts top-level and class-level constant assignments where
    the value is a literal (number, string, bool, None).
    """
    constants: Dict[str, Any] = {}

    class ConstantVisitor(ast.NodeVisitor):
        def __init__(self):
            self.in_class = False

        def visit_ClassDef(self, node):
            old_in_class = self.in_class
            self.in_class = True
            self.generic_visit(node)
            self.in_class = old_in_class

        def visit_FunctionDef(self, node):
            # Do not descend into function/method bodies
            return

        def visit_Assign(self, node):
            # Only collect if we are at module level or inside a class
            if not isinstance(node.parent, (ast.FunctionDef, ast.AsyncFunctionDef)):
                for target in node.targets:
                    if isinstance(target, ast.Name) and isinstance(node.value, ast.Constant):
                        constants[target.id] = node.value.value
            self.generic_visit(node)

        def visit_AnnAssign(self, node):
            if not isinstance(node.parent, (ast.FunctionDef, ast.AsyncFunctionDef)):
                if (isinstance(node.target, ast.Name)
                        and node.value is not None
                        and isinstance(node.value, ast.Constant)):
                    constants[node.target.id] = node.value.value
            self.generic_visit(node)

    try:
        with open(source_path, "r", encoding="utf-8") as f:
            tree = ast.parse(f.read())
    except (OSError, SyntaxError):
        return constants

    # Attach parent references for scope detection
    for node in ast.walk(tree):
        for child in ast.iter_child_nodes(node):
            child.parent = node

    visitor = ConstantVisitor()
    visitor.visit(tree)
    return constants
>>>>

**FOLLOW:** This fix changes the set of constants available for grounding in `_verify_z3_v2_shadow`. Claims that previously matched inner‑scope constants will now fail to ground, potentially increasing UNCERTAIN verdicts. This is correct behavior (prevents false proofs), but may reduce the coverage of the B‑Cell v2. No other functions call `_extract_constants_from_ast`; the only downstream impact is on `_verify_z3_v2_shadow` and its callers (`b_cell_v2_shadow`). The shadow log will show fewer “grounded” proofs, which should be reviewed for false positives. The fix also requires adding a `parent` attribute to AST nodes (safe as we only attach during visitation).
